<template><main class="page"><RouterLink to="/super-admin">Back</RouterLink><h1>Workspace Admins</h1><div class="card"><input v-model="search" placeholder="Search email"/><select v-model="workspaceId"><option value="all">All workspaces</option><option v-for="w in workspaces" :key="w.id" :value="w.id">{{w.name}}</option></select><button @click="load">Search</button></div><div class="card"><h2>Create Workspace Admin</h2><form @submit.prevent="create"><select v-model="createWorkspaceId" required><option value="" disabled>Select workspace</option><option v-for="w in workspaces" :key="w.id" :value="w.id">{{w.name}}</option></select><input v-model="email" type="email" required/><button>Create and send setup</button></form></div><table><thead><tr><th>Email</th><th>Workspace</th><th>Primary</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="a in admins" :key="a.id"><td>{{a.auth_email}}</td><td>{{a.workspace_name}}</td><td>{{a.is_primary_admin?'Yes':'No'}}</td><td>{{a.is_active?'Active':'Suspended'}}</td><td><button @click="toggle(a)" :disabled="a.is_primary_admin">{{a.is_active?'Suspend':'Restore'}}</button><button @click="reset(a.id)">Reset password</button><button @click="primary(a)">Make primary</button></td></tr></tbody></table></main></template>
<script setup lang="ts">import{onMounted,ref}from"vue";import{RouterLink}from"vue-router";import{createWorkspaceAdmin,listWorkspaceAdmins,sendWorkspaceAdminReset,setWorkspaceAdminStatus,type SuperWorkspaceAdmin}from"../../services/superWorkspaceAdminService";import{listWorkspaces,setPrimaryWorkspaceAdmin,type SuperWorkspace}from"../../services/superWorkspaceService";const admins=ref<SuperWorkspaceAdmin[]>([]),workspaces=ref<SuperWorkspace[]>([]),search=ref(""),workspaceId=ref("all"),createWorkspaceId=ref(""),email=ref("");const load=async()=>admins.value=await listWorkspaceAdmins(search.value,workspaceId.value);const create=async()=>{await createWorkspaceAdmin(createWorkspaceId.value,email.value);email.value="";await load();};const toggle=async(a:SuperWorkspaceAdmin)=>{await setWorkspaceAdminStatus(a.id,!a.is_active);await load();};const reset=async(id:string)=>{await sendWorkspaceAdminReset(id);};const primary=async(a:SuperWorkspaceAdmin)=>{if(confirm("Reassign Primary Workspace Admin? This Super Admin-only action changes peer-management authority.")){await setPrimaryWorkspaceAdmin(a.workspace_id,a.id);await load();}};onMounted(async()=>{workspaces.value=await listWorkspaces();await load();});</script>
